/// <summary>
/// A runnable job to clean up Security Serialization XML by removing all sub-nodes
/// under <c>_x003C_CustomizationsForTypeList_x003E_k__BackingField</c>.
/// </summary>
internal final class METCleanupSecurityCustomizationJob
{
}

Method.Source:
/// <summary>
/// Entry point for the job.
/// </summary>
/// <param name = "_args">Standard arguments.</param>
public static void main(Args _args)
{
    METCleanupSecurityCustomizationJob job = new METCleanupSecurityCustomizationJob();
    job.run();
}

/// <summary>
/// Executes the file upload, XML parsing/cleanup, and downloads the file back.
/// </summary>
public void run()
{
    FileUploadTemporaryStorageResult uploadResult;
    System.IO.Stream memoryStream;
    System.Xml.XmlDocument xmlDoc;
    System.Xml.XmlNodeList nodes;
    System.Xml.XmlNode node;
    System.IO.MemoryStream outStream;
    str originalFileName;
    str cleanedFileName;
    str ext;
    str baseName;
    int nodesCleaned = 0;
    int nodesCount;
    int i;

    uploadResult = File::GetFileFromUser();

    if (!uploadResult || !uploadResult.getUploadStatus())
    {
        info("Upload cancelled or failed.");
        return;
    }

    memoryStream = uploadResult.openResult();
    if (!memoryStream)
    {
        error("Failed to retrieve uploaded file stream.");
        return;
    }

    xmlDoc = new System.Xml.XmlDocument();
    xmlDoc.Load(memoryStream);

    // Find the _x003C_CustomizationsForTypeList_x003E_k__BackingField nodes using a namespace-agnostic XPath.
    nodes = xmlDoc.SelectNodes("//*[local-name()='_x003C_CustomizationsForTypeList_x003E_k__BackingField']");

    if (nodes.get_Count() == 0)
    {
        warning("Target node '_x003C_CustomizationsForTypeList_x003E_k__BackingField' not found in the XML file.");
        return;
    }

    nodesCount = nodes.get_Count();
    for (i = 0; i < nodesCount; i++)
    {
        node = nodes.Item(i);
        if (node)
        {
            node.RemoveAll();
            nodesCleaned++;
        }
    }

    info(strFmt("Successfully cleaned %1 node(s).", nodesCleaned));

    // Save cleaned XML back to a stream
    outStream = new System.IO.MemoryStream();
    xmlDoc.Save(outStream);
    outStream.Seek(0, System.IO.SeekOrigin::Begin);

    // Determine filename
    originalFileName = uploadResult.getFileName();
    cleanedFileName = "SecurityCustomizations_Cleaned.xml";
    if (originalFileName)
    {
        ext = System.IO.Path::GetExtension(originalFileName);
        baseName = System.IO.Path::GetFileNameWithoutExtension(originalFileName);
        cleanedFileName = baseName + "_Cleaned" + ext;
    }

    // Send cleaned file back to the user
    File::SendFileToUser(outStream, cleanedFileName);
}
